using System.ComponentModel;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Logging;
using OpenAI;

var builder = Host.CreateApplicationBuilder(args);

builder.Services.AddChatClient(b => b
    .UseOpenAIChatClient(
        modelId: "gpt-4o-mini-2024-07-18",
        new OpenAIClient(
            builder.Configuration["AI:ApiKey"]
                ?? Environment.GetEnvironmentVariable("OPENAI_API_KEY")
                ?? throw new InvalidOperationException(
                    "Set AI:ApiKey in configuration or OPENAI_API_KEY environment variable."))));

builder.Services.AddSingleton<ResearchTools>();
builder.Services.AddSingleton<NoteTools>();

using var host = builder.Build();

var chatClient = host.Services.GetRequiredService<IChatClient>();
var researchTools = host.Services.GetRequiredService<ResearchTools>();
var noteTools = host.Services.GetRequiredService<NoteTools>();
var loggerFactory = host.Services.GetRequiredService<ILoggerFactory>();

var tools = new List<AITool>
{
    AIFunctionFactory.Create(researchTools.SearchWeb),
    AIFunctionFactory.Create(noteTools.AddNote),
    AIFunctionFactory.Create(noteTools.GetNotes),
};

var agent = new ChatClientAgent(
    chatClient,
    name: "ResearchAgent",
    description: "An agent that researches topics by searching the web and taking notes.",
    instructions: """
        You are a research assistant. When given a topic:
        1. Search the web for relevant information using multiple queries.
        2. Take notes on key findings using the note-taking tool.
        3. After gathering enough information, retrieve your notes and produce a final summary.
        Be thorough but concise. Cite your sources.
        """,
    tools: tools,
    loggerFactory: loggerFactory,
    serviceProvider: host.Services);

Console.Write("Enter a research topic: ");
var topic = Console.ReadLine();
if (string.IsNullOrWhiteSpace(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\nResearching: {topic}\n");

var session = new AgentSession();
var response = await agent.RunAsync(
    $"Research the following topic and provide a comprehensive summary: {topic}",
    session,
    cancellationToken: CancellationToken.None);

Console.WriteLine("=== Research Summary ===\n");
Console.WriteLine(response.Text);

// -- Tool implementations --

public sealed class ResearchTools
{
    private static readonly HttpClient HttpClient = new();

    [Description("Searches the web for information on a given query and returns relevant results.")]
    public async Task<string> SearchWeb(
        [Description("The search query to look up")] string query)
    {
        // Simulated web search — in production, plug in Bing Search API or similar.
        // Returns realistic placeholder results to demonstrate the tool pattern.
        await Task.Delay(100); // Simulate network latency

        return $"""
            Search results for: "{query}"

            1. Wikipedia - {query}
               Summary: Comprehensive overview covering history, key concepts, and current developments related to {query}.
               URL: https://en.wikipedia.org/wiki/{Uri.EscapeDataString(query)}

            2. Research Paper - Recent Advances in {query}
               Summary: Academic paper discussing latest findings and methodologies in the field.
               URL: https://arxiv.org/search/?query={Uri.EscapeDataString(query)}

            3. News - Latest developments in {query}
               Summary: Recent news coverage highlighting breakthroughs and industry applications.
               URL: https://news.example.com/{Uri.EscapeDataString(query)}
            """;
    }
}

public sealed class NoteTools
{
    private readonly List<string> _notes = [];

    [Description("Saves a research note for later reference when building the summary.")]
    public string AddNote(
        [Description("The note content to save")] string note)
    {
        _notes.Add(note);
        return $"Note saved (total notes: {_notes.Count}).";
    }

    [Description("Retrieves all saved research notes.")]
    public string GetNotes()
    {
        if (_notes.Count == 0)
            return "No notes saved yet.";

        return string.Join("\n\n---\n\n", _notes.Select((n, i) => $"Note {i + 1}: {n}"));
    }
}

